; extra.asm -- chapter 44: a life too many
; generated by gen44.py
        INCLUDE "msx.inc"
        OUTPUT "extra.rom"
        ORG $4000
        CART_HEADER init
VARS    EQU RAM_START + $100    ; the program's variables: the code is in ROM
        INCLUDE "bios.inc"
stat    EQU VARS                ; the status isr read: F, 5S, C, a sprite's number
ticks   EQU VARS + 1            ; frames counted by isr, two bytes
seed    EQU VARS + 3            ; random's state, two bytes (chapter 41)
state   EQU VARS + 5            ; TITLE, PLAY, HIT or OVER
left    EQU VARS + 6            ; the steps left of HIT or of OVER
lives   EQU VARS + 7
gems    EQU VARS + 8            ; the gems of the round still lying
roundno EQU VARS + 9            ; the round, BCD
held    EQU VARS + 10           ; the keys and the stick: a 0 for each held
stale   EQU VARS + 11           ; frames whose C play1 does not believe
shownl  EQU VARS + 12           ; the lives on the status line
queued  EQU VARS + 13           ; the names queued for the sends
queue   EQU VARS + $10          ; 16 names: the VRAM address, then the name
copy    EQU VARS + $40          ; the sprites' attributes: Y, X, pattern, colour
runner  EQU copy                ; the runner's Y and X
faces   EQU copy + 4            ; and the faces', four each
steps   EQU VARS + $60          ; each face's step, -4 to 4
due     EQU VARS + $68          ; lines owed to the game's steps, two bytes
value   EQU VARS + $6A          ; a gem's points, BCD
bonus   EQU VARS + $6B          ; the round's bonus, in tens, BCD
tock    EQU VARS + $6C          ; steps to the bonus's next drop
awarded EQU VARS + $6D          ; 1 when the game's life more is won
ENGINE  EQU $C000               ; chapter 37's player, in a page of its own:
beats   EQU ENGINE              ; its ticks, two bytes (chapter 37's ticks)
owed    EQU ENGINE + 2          ; lines owed to the player, two bytes
lines   EQU ENGINE + 4          ; the machine's lines a frame: 313 or 262
tick    EQU ENGINE + 6          ; ticks still to the next row
songp   EQU ENGINE + 7          ; the song's step, two bytes (chapter 37's step)
barno   EQU ENGINE + 9          ; the step's number
rowno   EQU ENGINE + 10         ; the row in the bar
shadow  EQU ENGINE + $20        ; R0 to R10, as the next tick sends them
chan_a  EQU shadow + 11         ; the channels, CHAN bytes each
chan_b  EQU chan_a + CHAN
chan_c  EQU chan_b + CHAN
chan_x  EQU chan_c + CHAN       ; the effect: a fourth channel, on C's registers
names   EQU $C400               ; the copy of the 768 names
score   EQU $C700               ; three BCD bytes (chapter 40)
hi      EQU score + 3           ; the best, three more
shown   EQU score + $100        ; the six bytes last sent, a page on
SAT     EQU $1B00               ; the sprites' attributes
SPAT    EQU $3800               ; and their patterns
TITLE   EQU 0                   ; the states
PLAY    EQU 1
HIT     EQU 2
OVER    EQU 3
PAPER   EQU 0                   ; the tiles' names: from BRICK up, a wall
ALLEY   EQU 1
GEM     EQU 2
BRICK   EQU 3
DIGIT0  EQU $30                 ; '0'
X_MIN   EQU 8                   ; a face's X: X_MIN to X_MAX
X_MAX   EQU 232
HOME_X  EQU 120                 ; the runner's home
HOME_Y  EQU 23
GEMS    EQU 8                   ; gems a round
LIVES   EQU 3
STILL   EQU 50                  ; steps held still at a touch
ENDS    EQU 150                 ; steps of GAME OVER
STEPL   EQU 262                 ; the lines of a step: the 60 Hz frame
BONUS0  EQU $99                 ; the bonus as a round begins, tens, BCD
EVERY   EQU 8                   ; steps for each ten it drops
CAP     EQU 5                   ; the round from which a gem is worth the most
MAXS    EQU 4                   ; a face's fastest, pixels a step
MAX_LIVES EQU 9
EXTRA_AT EQU $10               ; the score's middle pair at 1,000 points
SCORE_AT EQU $1800 + 7           ; row 0: the score's first digit
LIVES_AT EQU $1800 + 20           ; the lives
HI_AT   EQU $1800 + 26             ; and the best's first digit
ROUND_AT EQU 744               ; the bottom line: the round's first digit
BONUS_AT EQU 763               ; and the bonus's
WAITS   EQU 0                   ; rows to wait; an effect: ticks to sound
NOTE    EQU 1                   ; the note, 0 for a rest
INSTR   EQU 2                   ; the instrument
PATTERN EQU 3                   ; the next event
VOLUME  EQU 5                   ; this tick's level in the volume table
PITCHES EQU 7                   ; this tick's semitones
FIRST   EQU 9                   ; the pitch table's first byte
MIXER   EQU 11                  ; the instrument's TONE and NOISE
NOISEP  EQU 12                  ; its noise's period
SHPER   EQU 13                  ; where in shadow its period goes
SHLEV   EQU 15                  ; and its level
TMASK   EQU 17                  ; R7 with its tone bit at 0
NMASK   EQU 18                  ; R7 with its noise bit at 0
PRIO    EQU 19                  ; an effect's priority
CHAN    EQU 20                  ; bytes a channel
IM2_TABLE EQU $C200             ; 257 bytes of $C3: every vector is $C3C3
IM2_JUMP  EQU $C3C3             ; and there, a JP to the routine
; WHERE IT BREAKS. game.asm whose award forgets that the life more is won
; once a game.
init:   di
        ld sp, SYS_AREA
        VDP_REG 1, $80          ; display off
        VDP_REG 0, $02          ; Graphic II
        VDP_REG 2, $06          ; names    $1800
        VDP_REG 3, $9F          ; colours  $2000, one set for three thirds
        VDP_REG 4, $00          ; shapes   $0000, one set for three thirds
        VDP_REG 5, $36          ; sprite attributes $1B00
        VDP_REG 6, $07          ; sprite patterns   $3800
        VDP_REG 7, $01          ; border black
        VRAM_WRITE SAT          ; no sprites yet
        ld a, $D0
        out (VDP_DATA), a
        ld hl, VARS             ; the variables' page, all 0: ticks,
        ld de, VARS + 1         ; the lives, the queue, stale and the rest
        ld bc, 255
        ld (hl), 0
        ldir
        VRAM_WRITE $0000        ; the four tiles' shapes
        ld hl, tiles
        ld bc, 32 << 8 | VDP_DATA
        otir
        VRAM_WRITE $0100        ; chapter 30's characters, codes 32 to 127
        ld hl, font
        ld b, 3                 ; three runs of 256 bytes
.font:  push bc
        ld b, 0
        otir
        pop bc
        djnz .font
        VRAM_WRITE $2000        ; the tiles' colours
        ld hl, tcols
        ld b, 32
        otir
        VRAM_WRITE $2100        ; the characters', black on white
        ld bc, 768
.fc:    ld a, $1F
        out (VDP_DATA), a
        dec bc
        ld a, b
        or c
        jr nz, .fc
        VRAM_WRITE SPAT         ; the runner, patterns 0 to 3, and a face, 4 to 7
        ld hl, sprites
        ld bc, 64 << 8 | VDP_DATA
        otir
        ld hl, nums             ; score 000000 and the best at the start,
        ld de, score
        ld bc, 6
        ldir
        ld hl, nums             ; as if on the screen: the title shows neither
        ld de, shown
        ld bc, 6
        ldir
        ld hl, ENGINE           ; the player's page, all 0
        ld de, ENGINE + 1
        ld bc, 255
        ld (hl), 0
        ldir
        ld a, ($002B)           ; bit 7 is 1 on a 50 Hz machine (chapter 4)
        rla
        ld hl, 262              ; 60 Hz ...
        jr nc, .rlines
        ld hl, 313              ; ... and 50 Hz
.rlines:ld (lines), hl
        ld hl, 0
        ld (owed), hl
        ld (beats), hl
        ld a, 1                 ; the first tick reads a row
        ld (tick), a
        xor a
        ld (barno), a
        ld (rowno), a
        ld hl, song - 6         ; the step before the first
        ld (songp), hl
        ld hl, start            ; shadow and the four channels
        ld de, shadow
        ld bc, 91
        ldir
        ld hl, IM2_TABLE        ; mode 2: the table, 257 bytes of $C3
        ld de, IM2_TABLE + 1
        ld bc, 256
        ld (hl), high IM2_JUMP
        ldir
        ld a, $C3               ; and at $C3C3, JP isr
        ld (IM2_JUMP), a
        ld hl, isr
        ld (IM2_JUMP + 1), hl
        ld a, high IM2_TABLE
        ld i, a                 ; I: the page of the table
        im 2
        ld a, TITLE
        call go                 ; the first state: title0 ends with EI
        di
        in a, (VDP_CTRL)        ; no signal left over (chapter 39)
        VDP_REG 1, $E2          ; display on, the frame's signal, sprites 16 x 16
main:   ei
frame:  halt                    ; isr: the status kept, the frame counted
woke:   call sends              ; 18  sprites, names queued, the status line
sent:   call run                ; 18  the state's work
ran:    jr frame                ; 13

; run: this frame's routine for the state held in state.
; go: A = a state -> it is the state, and its start routine has run.
;     Both use every register that routine uses (chapter 41)
run:    ld a, (state)           ; 14
        ld hl, frames           ; 11
        jr table                ; 13
go:     ld (state), a           ; 14
        ld hl, starts           ; 11
table:  add a, a                ;  5  two bytes a state
        add a, l                ;  5
        ld l, a                 ;  5  the tables do not cross a page
        ld a, (hl)              ;  8
        inc l                   ;  5
        ld h, (hl)              ;  8
        ld l, a                 ;  5
        jp (hl)                 ;  5  and its RET goes back to the caller

; isr: every frame. The status kept in stat, the signal let down; the frame
; counted, and its lines owed to the game's steps; the keys and the stick read
; while the frame is young; then chapter 37's player: when pace gives it a
; tick, last tick's registers to the PSG first, and the next tick worked out.
; Keeps every register it uses
isr:    push af                 ; 12
        in a, (VDP_CTRL)        ; 12  the status: F, 5S, C, a sprite's number
        ld (stat), a            ; 14
        push bc                 ; 12
        push de                 ; 12
        push hl                 ; 12
        push ix                 ; 17
        ld hl, (ticks)          ; 17
        inc hl                  ;  7
        ld (ticks), hl          ; 17
        ld hl, (due)            ; 17  the lines owed to the game ...
        ld de, (lines)          ; 22
        add hl, de              ; 12  ... and this frame's, 262 or 313
        ld (due), hl            ; 17
        call input              ; 18  held
        call pace               ; 18  carry: the player's tick (chapter 37)
        jr nc, .done            ; 13, or 8
        call tochip             ; 18
        call play               ; 18
.done:  pop ix                  ; 16
        pop hl                  ; 11
        pop de                  ; 11
        pop bc                  ; 11
        pop af                  ; 11
isrend: ei                      ;  5
        ret                     ; 11

; paced: B = the game's steps owed, one for each STEPL lines that isr has
; added to due, which keeps what is left over. Uses B, DE, HL
paced:  ld hl, (due)            ; 17
        ld de, -STEPL           ; 11
        ld b, 0                 ;  8
.more:  add hl, de              ; 12  carry: STEPL lines more
        jr nc, .rest            ; 13, or 8
        inc b                   ;  5  a step
        jr .more                ; 13
.rest:  sbc hl, de              ; 17  the last STEPL given back: no carry
        ld (due), hl            ; 17
        ret                     ; 11

; input: in the interrupt, the cursor keys and joystick 1 together (chapters
; 34 and 35) -> held, in register 14's way: bits 0 to 3 up, down, left,
; right, bit 4 SPACE or button A, a 0 for each held. Uses A, BC, HL
input:  call keys               ; 18  row 8 in register 14's way
        ld c, a                 ;  5
        xor a                   ;  5  port 1
        call joy                ; 18  its register 14
        and c                   ;  5  held on either
        ld (held), a            ; 14
        ret                     ; 11

; fx: A = a sound -> chapter 37's sfx, with the interrupts off, for sfx and
; the player share chan_x. Uses A, DE, HL, IX
fx:     di                      ;  5
        call sfx                ; 18
        ei                      ;  5
        ret                     ; 11

; sends: straight after HALT, before the paper: the copy of the sprites'
; attributes, the names the frame before queued, and the status line's
; digits that changed. Uses A, BC, DE, HL
sends:  VRAM_WRITE SAT          ; 40
        ld hl, copy             ; 11
        ld bc, 21 << 8 | VDP_DATA ; 11  five sprites and the end
        otir                    ; 23 a byte, 18 the last
        ld hl, queued           ; 11
        ld a, (hl)              ;  8
        or a                    ;  5
        jr z, status            ; 13, or 8  none queued
        ld b, a                 ;  5
        ld (hl), 0              ; 11  none from now on
        ld l, low queue         ;  8  the queue in queued's page
.name:  ld a, (hl)              ;  8
        out (VDP_CTRL), a       ; 12
        inc l                   ;  5
        ld a, (hl)              ;  8
        out (VDP_CTRL), a       ; 12  its address
        inc l                   ;  5
        ld a, (hl)              ;  8
        out (VDP_DATA), a       ; 12  and its name
        inc l                   ;  5
        djnz .name              ; 14, or 9
; status: the score, the best and the lives, what changed (chapter 40)
status: ld hl, score            ; 11
        ld de, SCORE_AT | $4000 ; 11
        call update             ; 18
        ld hl, hi               ; 11
        ld de, HI_AT | $4000    ; 11
        call update             ; 18
        ld a, (lives)           ; 14
        ld hl, shownl           ; 11
        cp (hl)                 ;  8
        ret z                   ; 12, or 6  shown already
        ld (hl), a              ;  8
        ld c, a                 ;  5
        ld a, low LIVES_AT      ;  8
        out (VDP_CTRL), a       ; 12
        ld a, high LIVES_AT | $40 ;  8
        out (VDP_CTRL), a       ; 12
        ld a, c                 ;  5
        or DIGIT0               ;  8  its digit
        out (VDP_DATA), a       ; 12
        ret                     ; 11

; update: HL = a number, three BCD bytes, with a copy of the three last sent
; 256 bytes on; DE = the VRAM address of its first digit, bit 6 set -> each
; byte that differs from its copy sent, and copied. Uses A, BC, DE, HL
update: ld b, 3                 ;  8  three bytes
.byte:  ld a, (hl)              ;  8  a byte of the number
        inc h                   ;  5  the page of the bytes sent
        cp (hl)                 ;  8
        jr z, .same             ; 13, or 8  on the screen already
        ld (hl), a              ;  8  it will be
        ld c, a                 ;  5
        ld a, e                 ;  5
        out (VDP_CTRL), a       ; 12
        ld a, d                 ;  5
        out (VDP_CTRL), a       ; 12  the address of its first digit
        ld a, c                 ;  5
        call putbcd             ; 18  its two names
.same:  inc e                   ;  5
        inc e                   ;  5  past its two names
        dec h                   ;  5  back to the number
        inc l                   ;  5  and its next byte
        djnz .byte              ; 14, or 9
        ret                     ; 11

; putbcd: A = a BCD byte, the VRAM address set -> its two digits sent, as
; the patterns from DIGIT0 (chapter 40's, with an OR). Uses A, C
putbcd: ld c, a                 ;  5
        rrca                    ;  5
        rrca                    ;  5
        rrca                    ;  5
        rrca                    ;  5  the first digit to bits 3 to 0
        and $0F                 ;  8
        or DIGIT0               ;  8  its pattern
        out (VDP_DATA), a       ; 12
        ld a, c                 ;  5
        and $0F                 ;  8  the second digit
        or DIGIT0               ;  8
        out (VDP_DATA), a       ; 12
        ret                     ; 11

; keys: row 8 of the keyboard -> A in register 14's way: the cursor keys as
; the four switches, SPACE as button A, a 0 for each held. The interrupts
; must be off. Uses A, C, HL
keys:   in a, (PPI_C)           ; 12
        and $F0                 ;  8  port C's top bits kept (chapter 34)
        or 8                    ;  8
        out (PPI_C), a          ; 12  row 8
        in a, (PPI_B)           ; 12  bits 7-4: RIGHT DOWN UP LEFT; bit 0: SPACE
        ld c, a                 ;  5
        rrca                    ;  5
        rrca                    ;  5
        rrca                    ;  5
        rrca                    ;  5
        and $0F                 ;  8
        ld hl, kbdjoy           ; 11
        add a, l                ;  5
        ld l, a                 ;  5
        ld a, c                 ;  5
        and 1                   ;  8  SPACE
        rlca                    ;  5
        rlca                    ;  5
        rlca                    ;  5
        rlca                    ;  5  into bit 4, button A's
        or (hl)                 ;  8  and the cursor keys as the switches
        or $E0                  ;  8
        ret                     ; 11

; joy: A = $00 for port 1, $40 for port 2 -> A = that port's register 14, a 0
; for each switch closed. Register 15's other seven bits are kept. The
; interrupts must be off. Uses A, B
joy:    ld b, a                 ;  5
        ld a, 15                ;  8
        out (PSG_ADDR), a       ; 12  register 15
        in a, (PSG_READ)        ; 12  as it is
        and $BF                 ;  8  bit 6: the port
        or b                    ;  5
        out (PSG_WRITE), a      ; 12
        ld a, 14                ;  8
        out (PSG_ADDR), a       ; 12  register 14
        in a, (PSG_READ)        ; 12  the port's pins
        ret                     ; 11

; walk: held -> the runner two pixels along X for LEFT or RIGHT, then two
; along Y for UP or DOWN, each where walled finds no wall (chapter 39), so
; that it slides along a wall it meets at a slant. Uses A, BC, DE, HL
walk:   ld bc, (runner)         ; 22  C = Y, B = X
        ld a, (held)            ; 14
        bit 2, a                ; 10  LEFT
        jr nz, .right           ; 13, or 8
        dec b                   ;  5
        dec b                   ;  5  two to the left
.right: bit 3, a                ; 10  RIGHT
        jr nz, .x               ; 13, or 8
        inc b                   ;  5
        inc b                   ;  5  two to the right
.x:     push bc                 ; 12
        call walled             ; 18  NZ: a wall there
        pop bc                  ; 11
        jr nz, .y               ; 13, or 8
        ld a, b                 ;  5
        ld (runner + 1), a      ; 14  the new X
.y:     ld bc, (runner)         ; 22  X as it is now, and Y
        ld a, (held)            ; 14
        bit 0, a                ; 10  UP
        jr nz, .down            ; 13, or 8
        dec c                   ;  5
        dec c                   ;  5  two up
.down:  bit 1, a                ; 10  DOWN
        jr nz, .w               ; 13, or 8
        inc c                   ;  5
        inc c                   ;  5  two down
.w:     push bc                 ; 12
        call walled             ; 18
        pop bc                  ; 11
        ret nz                  ; 12, or 6  a wall
        ld a, c                 ;  5
        ld (runner), a          ; 14  the new Y
        ret                     ; 11

; cell: B = X, C = a line -> HL: the cell of the copy of the names that holds
; the pixel. Keeps BC. Uses A, DE
cell:   ld a, c                 ;  5
        and $F8                 ;  8  the row x 8
        ld l, a                 ;  5
        ld h, 0                 ;  8
        add hl, hl              ; 12
        add hl, hl              ; 12  the row x 32
        ld a, b                 ;  5
        rrca                    ;  5
        rrca                    ;  5
        rrca                    ;  5
        and $1F                 ;  8  the column
        add a, l                ;  5
        ld l, a                 ;  5
        ld de, names            ; 11
        add hl, de              ; 12
        ret                     ; 11

; walled: B = X, C = Y of a ball's place -> NZ if a wall is under any of its
; 16 x 16 pixels: the cells from column X / 8 to (X + 15) / 8 and from row
; (Y + 1) / 8 to (Y + 16) / 8, for a sprite's first line is Y + 1 (chapter
; 26). A wall is any name from the brick's up. Uses A, BC, DE, HL
walled: inc c                   ;  5  the first line
        call cell               ; 18  HL: the cell of the top left pixel
        ld a, b                 ;  5
        and 7                   ;  8
        ld d, 2                 ;  8  two columns on a column's edge,
        jr z, .cols             ; 13, or 8
        inc d                   ;  5  three anywhere else
.cols:  ld a, c                 ;  5
        and 7                   ;  8
        ld e, 2                 ;  8  and two rows, or three
        jr z, .rows             ; 13, or 8
        inc e                   ;  5
.rows:  ld b, d                 ;  5
        push hl                 ; 12
.cell:  ld a, (hl)              ;  8
        cp BRICK                ;  8  the bricks and the letters
        jr nc, .wall            ; 13, or 8
        inc hl                  ;  7
        djnz .cell              ; 14, or 9
        pop hl                  ; 11
        ld bc, 32               ; 11
        add hl, bc              ; 12  the row of cells below
        dec e                   ;  5
        jr nz, .rows            ; 13, or 8
        ret                     ; 11  Z: no wall
.wall:  pop hl                  ; 11
        or a                    ;  5  A is BRICK or more
        ret                     ; 11  NZ: a wall

; patrol: IX = a face's attributes in the copy, HL = its step -> X a step
; on; a step that would take it outside X_MIN to X_MAX, the walls' inside,
; turns it, and it steps the other way instead. Uses A
patrol: ld a, (ix + 1)          ; 21  X
        add a, (hl)             ;  8  and its step
        sub X_MIN               ;  8
        cp X_MAX - X_MIN + 1    ;  8  carry from X_MIN to X_MAX
        jr c, .x                ; 13, or 8
        ld a, (hl)              ;  8
        neg                     ; 10
        ld (hl), a              ;  8  the other way
        add a, (ix + 1)         ; 21
        sub X_MIN               ;  8
.x:     add a, X_MIN            ;  8
        ld (ix + 1), a          ; 21
        ret                     ; 11

; step: a frame of the play: the runner, then each face. Uses A, BC, DE,
; HL, IX
step:   call walk               ; 18
        ld ix, faces            ; 16
        ld hl, steps            ; 11
        ld de, 4                ; 11
        ld b, 4                 ;  8  four faces
.face:  call patrol             ; 18
        add ix, de              ; 17  the next face's attributes
        inc l                   ;  5  and its step
        djnz .face              ; 14, or 9
        ret                     ; 11

; pick: the cells under the runner's 16 x 16 pixels, as walled finds them ->
; each with a gem taken by took. Uses A, BC, DE, HL
pick:   ld bc, (runner)         ; 22  C = Y, B = X
        inc c                   ;  5  the first line
        call cell               ; 18  HL: the cell of the top left pixel
        ld a, b                 ;  5
        and 7                   ;  8
        ld d, 2                 ;  8  two columns on a column's edge,
        jr z, .cols             ; 13, or 8
        inc d                   ;  5  three anywhere else
.cols:  ld a, c                 ;  5
        and 7                   ;  8
        ld e, 2                 ;  8  and two rows, or three
        jr z, .rows             ; 13, or 8
        inc e                   ;  5
.rows:  ld b, d                 ;  5
        push hl                 ; 12
.cell:  ld a, (hl)              ;  8
        cp GEM                  ;  8
        call z, took            ; 18, or 11  a gem
        inc hl                  ;  7
        djnz .cell              ; 14, or 9
        pop hl                  ; 11
        ld bc, 32               ; 11
        add hl, bc              ; 12  the row of cells below
        dec e                   ;  5
        jr nz, .rows            ; 13, or 8
        ret                     ; 11

; took: HL = a gem's cell in the copy of the names -> the cell paper again,
; queued; the gem's points, its sound, and a life if one is due; a gem
; fewer. Keeps BC, DE, HL. Uses A, IX
took:   push bc                 ; 12
        push de                 ; 12
        push hl                 ; 12
        xor a                   ;  5  PAPER
        call post               ; 18
        ld a, (value)           ; 14  the round's points for a gem
        call addsc              ; 18
        ld hl, gems             ; 11
        dec (hl)                ; 12  a gem fewer
        ld a, S_GEM             ;  8
        call fx                 ; 18
        call award              ; 18
        pop hl                  ; 11
        pop de                  ; 11
        pop bc                  ; 11
        ret                     ; 11

; post: HL = a cell of the copy of the names, A = a name -> the name written
; there and queued for the next frame's sends. Uses A, BC, DE, HL
post:   ld (hl), a              ;  8
        ld c, a                 ;  5  the name
        ld de, ($1800 + $4000 - names) & $FFFF ; 11
        add hl, de              ; 12  its VRAM address, plus $4000 for writing
        ex de, hl               ;  5  in DE
        ld hl, queued           ; 11
        ld a, (hl)              ;  8
        inc (hl)                ; 12  one more
        ld b, a                 ;  5
        add a, a                ;  5
        add a, b                ;  5  three bytes each
        add a, low queue        ;  8
        ld l, a                 ;  5  the queue in queued's page
        ld (hl), e              ;  8
        inc l                   ;  5
        ld (hl), d              ;  8
        inc l                   ;  5
        ld (hl), c              ;  8
        ret                     ; 11

; sow: a gem in a free cell of a corridor: one of its eight rows and a
; column from 1 to 30, chosen by random, again while the cell is a wall, is
; not paper, or lies under the runner or where a step takes it: its 3 x 3
; cells and one more all round. Uses A, BC, DE, HL
sow:    call random             ; 18
        and 7                   ;  8  one of the eight rows
        ld e, a                 ;  5
        ld d, 0                 ;  8
        ld hl, rows             ; 11
        add hl, de              ; 12
        ld c, (hl)              ;  8  C: the row
        call random             ; 18
        and 31                  ;  8  the column
        jr z, sow               ; 13, or 8  0, the left wall: again
        cp 31                   ;  8
        jr z, sow               ; 13, or 8  31, the right wall
        ld b, a                 ;  5  B: the column
        ld a, (runner)          ; 14  the runner's Y
        inc a                   ;  5  its first line
        rrca                    ;  5
        rrca                    ;  5
        rrca                    ;  5
        and 31                  ;  8  its first row
        ld e, a                 ;  5
        ld a, c                 ;  5
        sub e                   ;  5
        inc a                   ;  5  from the row above its first
        cp 5                    ;  8  carry: one of those five rows
        jr nc, .free            ; 13, or 8
        ld a, (runner + 1)      ; 14  its X
        rrca                    ;  5
        rrca                    ;  5
        rrca                    ;  5
        and 31                  ;  8  its first column
        ld e, a                 ;  5
        ld a, b                 ;  5
        sub e                   ;  5
        inc a                   ;  5
        cp 5                    ;  8
        jr c, sow               ; 13, or 8  near the runner: again
.free:  ld l, c                 ;  5
        ld h, 0                 ;  8
        add hl, hl              ; 12
        add hl, hl              ; 12
        add hl, hl              ; 12
        add hl, hl              ; 12
        add hl, hl              ; 12  the row x 32
        ld a, l                 ;  5
        or b                    ;  5  and the column
        ld l, a                 ;  5
        ld de, names            ; 11
        add hl, de              ; 12  HL: the cell in the copy
        ld a, (hl)              ;  8
        cp PAPER                ;  8
        jr nz, sow              ; 13, or 8  a gem there already: again
        ld a, GEM               ;  8
        jp post                 ; 11  the gem, queued

; round: the next round: its number; a gem's points, ten for each round up
; to CAP; the faces' speeds; the bonus full; the two numbers on the bottom
; line through the queue; GEMS gems sown, and as many to take. Uses A, BC,
; DE, HL
round:  ld a, (roundno)         ; 14
        add a, 1                ;  8
        daa                     ;  5  one more, in BCD
        ld (roundno), a         ; 14
        ld hl, names + ROUND_AT ; 11
        call post2              ; 18  its two digits
        ld a, (roundno)         ; 14
        cp CAP                  ;  8  from round CAP on ...
        jr c, .value            ; 13, or 8
        ld a, CAP               ;  8  ... the most
.value: add a, a                ;  5
        add a, a                ;  5
        add a, a                ;  5
        add a, a                ;  5  a digit on: tens of points
        ld (value), a           ; 14
        call speeds             ; 18
        ld a, BONUS0            ;  8
        ld (bonus), a           ; 14
        ld hl, names + BONUS_AT ; 11
        call post2              ; 18
        ld a, EVERY             ;  8
        ld (tock), a            ; 14
        ld b, GEMS              ;  8
.gem:   push bc                 ; 12
        call sow                ; 18
        pop bc                  ; 11
        djnz .gem               ; 14, or 9
        ld a, GEMS              ;  8
        ld (gems), a            ; 14
        ret                     ; 11

; speeds: each face's speed for the round: its first speed and one more for
; each round after the first, never more than MAXS, the way it goes now
; kept. Uses A, BC, DE, HL
speeds: ld a, (roundno)         ; 14
        dec a                   ;  5  the rounds before this one
        ld c, a                 ;  5
        ld hl, fsteps           ; 11  the first steps
        ld de, steps            ; 11
        ld b, 4                 ;  8
.face:  ld a, (hl)              ;  8
        bit 7, a                ; 10
        jr z, .up               ; 13, or 8
        neg                     ; 10  its first speed
.up:    add a, c                ;  5  one more a round
        cp MAXS + 1             ;  8
        jr c, .way              ; 13, or 8
        ld a, MAXS              ;  8
.way:   ex de, hl               ;  5
        bit 7, (hl)             ; 14  the way it goes now
        jr z, .put              ; 13, or 8
        neg                     ; 10
.put:   ld (hl), a              ;  8
        ex de, hl               ;  5
        inc hl                  ;  7
        inc de                  ;  7
        djnz .face              ; 14, or 9
        ret                     ; 11

; cleared: the round's last gem gone: its sound, what is left of the bonus
; added, a life if one is due, and the next round. Uses every register but IY
cleared: ld a, S_ROUND          ;  8
        call fx                 ; 18
        ld a, (bonus)           ; 14
        call addten             ; 18
        call award              ; 18
        jp round                ; 11

; drop: a step of the bonus's count: every EVERY steps a ten fewer, down to
; none, its two digits queued. Uses A, BC, DE, HL
drop:   ld hl, tock             ; 11
        dec (hl)                ; 12
        ret nz                  ; 12, or 6
        ld (hl), EVERY          ; 11
        ld a, (bonus)           ; 14
        or a                    ;  5
        ret z                   ; 12, or 6  none left
        sub 1                   ;  8
        daa                     ;  5  a ten fewer, in BCD (chapter 9)
        ld (bonus), a           ; 14
        ld hl, names + BONUS_AT ; 11  its first digit's cell
        jp post2                ; 11

; post2: A = a BCD byte, HL = the cell of its first digit in the copy of the
; names -> its two digits posted. Uses A, BC, DE, HL
post2:  push hl                 ; 12
        push af                 ; 12
        rrca                    ;  5
        rrca                    ;  5
        rrca                    ;  5
        rrca                    ;  5
        and 15                  ;  8  the first digit
        add a, DIGIT0           ;  8
        call post               ; 18
        pop af                  ; 11
        pop hl                  ; 11
        inc hl                  ;  7  the next cell
        and 15                  ;  8  the second
        add a, DIGIT0           ;  8
        jp post                 ; 11

; addten: A = points in tens, two BCD digits -> added to score: its second
; digit to the tens, its first to the hundreds, the carry taken on with ADC
; and DAA (chapter 9). Uses A, BC, HL
addten: ld c, a                 ;  5
        rrca                    ;  5
        rrca                    ;  5
        rrca                    ;  5
        rrca                    ;  5
        and 15                  ;  8  the first digit, as hundreds
        ld b, a                 ;  5
        ld a, c                 ;  5
        add a, a                ;  5
        add a, a                ;  5
        add a, a                ;  5
        add a, a                ;  5  the second, as tens
        ld hl, score + 2        ; 11  the tens and the units
        add a, (hl)             ;  8
        daa                     ;  5
        ld (hl), a              ;  8
        dec hl                  ;  7  the thousands and the hundreds
        ld a, b                 ;  5
        adc a, (hl)             ;  8  with the tens' carry
        daa                     ;  5
        ld (hl), a              ;  8
        dec hl                  ;  7  and the first two digits
        ld a, (hl)              ;  8
        adc a, 0                ;  8
        daa                     ;  5
        ld (hl), a              ;  8
        ret                     ; 11

; play0: nothing to set: the steps come from due
play0:  ret                     ; 11

; play1: THE FRAME OF THE PLAY. The next round when the last gem is gone;
; for each step owed, a step of the runner and of every face, and of the
; bonus's count; the gems under the runner; the best score; and a touch: C,
; which isr kept from the frame just drawn. Uses every register but IY
play1:  ld a, (gems)            ; 14
        or a                    ;  5
        call z, cleared         ; 18, or 11  the last gem gone: the next round
        call paced              ; 18  B: the steps owed
.step:  push bc                 ; 12
        call step               ; 18  the runner and the faces
        call drop               ; 18  the bonus
        pop bc                  ; 11
        djnz .step              ; 14, or 9
        call pick               ; 18  its gems
        call best               ; 18  hi kept the best
        ld hl, stale            ; 11
        ld a, (hl)              ;  8
        or a                    ;  5
        jr z, .look             ; 13, or 8
        dec (hl)                ; 12  a frame whose C is not believed
        ret                     ; 11
.look:  ld a, (stat)            ; 14
        and $20                 ;  8  C
        ret z                   ; 12, or 6  no sprites met
touch:  ld a, HIT               ;  8
        jp go                   ; 11  a face touched the runner

; hit0: a life fewer, its sound, and the game held still
hit0:   ld hl, lives            ; 11
        dec (hl)                ; 12  the status line shows it next frame
        ld a, STILL             ;  8
        ld (left), a            ; 14
        ld a, S_TOUCH           ;  8
        jp fx                   ; 11

; hit1: the steps owed off the wait, and at its end GAME OVER, or the
; runner home again
hit1:   call countdown          ; 18
        ret nz                  ; 12, or 6
        ld a, (lives)           ; 14
        or a                    ;  5
        ld a, OVER              ;  8
        jp z, go                ; 11  no lives left
        ld hl, HOME_X << 8 | HOME_Y ; 11
        ld (runner), hl         ; 17  home again, Y and X
        ld a, 1                 ;  8
        ld (stale), a           ; 14  its C is the frame before it went
home:   ld a, PLAY              ;  8
        jp go                   ; 11

; countdown: left less the steps owed, down to 0 -> Z at 0. Uses A, B, DE, HL
countdown: call paced           ; 18  B: the steps owed
        ld hl, left             ; 11
        ld a, (hl)              ;  8
        sub b                   ;  5
        jr nc, .left            ; 13, or 8
        xor a                   ;  5  no less than none
.left:  ld (hl), a              ;  8
        or a                    ;  5
        ret                     ; 11

; award: a life more, once a game, when the score reaches 1,000 points, and
; its sound; never past MAX_LIVES, the most a digit shows. Uses A, DE, HL, IX
award:  ld hl, score            ; 11
        ld a, (hl)              ;  8  the first two digits
        or a                    ;  5
        jr nz, .life            ; 13, or 8  10,000 or more
        inc hl                  ;  7
        ld a, (hl)              ;  8  the thousands and the hundreds
        cp EXTRA_AT             ;  8
        ret c                   ; 12, or 6  below 1,000
.life:  ld a, 1                 ;  8
        ld (awarded), a         ; 14
        ld hl, lives            ; 11
        ld a, (hl)              ;  8
        cp MAX_LIVES            ;  8
        jr nc, .sound           ; 13, or 8  as many as a digit shows
        inc (hl)                ; 12  the status line shows it next frame
.sound: ld a, S_EXTRA           ;  8
        jp fx                   ; 11

; title0: the title's 768 names at 29 T-states a name (chapter 20); the score
; of the last game, the lives a game begins with and the best, all to be
; sent; the runner and a face
title0: di                      ;  5
        VRAM_WRITE $1800        ; 40
        ei                      ;  5
        ld hl, tnames           ; 11
        ld bc, VDP_DATA         ; 11  B: 0, a run of 256; C: the port
        ld d, 3                 ;  8  three runs
.run:   outi                    ; 18
        jp nz, .run             ; 11
        dec d                   ;  5
        jr nz, .run             ; 13, or 8
        ld hl, shown            ; 11
        ld b, 6                 ;  8
.none:  ld (hl), $FF            ; 11  none of the digits shown
        inc l                   ;  5
        djnz .none              ; 14, or 9
        ld a, LIVES             ;  8
        ld (lives), a           ; 14
        ld a, $FF               ;  8
        ld (shownl), a          ; 14
        ld hl, tcopy            ; 11  the two sprites, and the face's step
        ld de, copy             ; 11
        ld bc, 9                ; 11
        ldir                    ; 23 a byte, 18 the last
        ld a, 2                 ;  8
        ld (steps), a           ; 14
        ret                     ; 11

; title1: the face a step on for each step owed; SPACE or button A held? The
; seed is the frame count, 1 for 0 (chapter 41), and a game begins
title1: call paced              ; 18
.step:  push bc                 ; 12
        ld ix, faces            ; 16  the title's face
        ld hl, steps            ; 11
        call patrol             ; 18
        pop bc                  ; 11
        djnz .step              ; 14, or 9
        ld a, (held)            ; 14  isr read them
        and $10                 ;  8  SPACE, button A
        ret nz                  ; 12, or 6
        ld hl, (ticks)          ; 17  the seed
        ld a, h                 ;  5
        or l                    ;  5
        jr nz, .seed            ; 13, or 8
        inc hl                  ;  7
.seed:  ld (seed), hl           ; 17
pressed: call setup             ; 18  the arena, the status line, the sprites
        call round              ; 18  the first round
        ld a, PLAY              ;  8
        jp go                   ; 11

; over0: GAME OVER, its sound, and ENDS steps of it
over0:  ld hl, otext            ; 11
        ld de, $1800 + 32 * 4 + 11 | $4000 ; 11
        di                      ;  5
        call say                ; 18
        ei                      ;  5
        ld a, ENDS              ;  8
        ld (left), a            ; 14
        ld a, S_OVER            ;  8
        jp fx                   ; 11

; over1: the steps owed off the wait, and at its end the title again
over1:  call countdown          ; 18
        ret nz                  ; 12, or 6
again:  ld a, TITLE             ;  8
        jp go                   ; 11

; setup: a new game. The arena into the copy of the names and to the VDP;
; score 0, none of its digits shown; three lives, none won; round 0; the
; sprites at their first places, the faces' first steps; no names queued
setup:  call arena              ; 18
        ld hl, score            ; 11
        ld b, 3                 ;  8
.zero:  ld (hl), 0              ; 11
        inc l                   ;  5
        djnz .zero              ; 14, or 9
        ld hl, shown            ; 11
        ld b, 6                 ;  8
.none:  ld (hl), $FF            ; 11  none of its digits shown: the sends send all
        inc l                   ;  5
        djnz .none              ; 14, or 9
        ld a, LIVES             ;  8
        ld (lives), a           ; 14
        ld a, $FF               ;  8
        ld (shownl), a          ; 14
        ld hl, first            ; 11  the sprites' first places
        ld de, copy             ; 11
        ld bc, 21               ; 11
        ldir                    ; 23 a byte, 18 the last
        ld hl, fsteps           ; 11  and the faces' first steps
        ld de, steps            ; 11
        ld bc, 4                ; 11
        ldir                    ; 23 a byte, 18 the last
        xor a                   ;  5
        ld (queued), a          ; 14
        ld (stale), a           ; 14
        ld (roundno), a         ; 14
        ld (awarded), a         ; 14
        ret                     ; 11

; arena: the names of the play into the copy of the names and to the VDP at
; once, 41 T-states a name in its rows: row 0 the status line's labels from
; row0, rows 1 to 22 a wall, 30 names from arows and a wall, and row 23 the
; bottom line from row23
arena:  di                      ;  5
        VRAM_WRITE $1800        ; 40
        ei                      ;  5
        ld hl, row0             ; 11  row 0
        ld de, names            ; 11
        call row32              ; 18
        ex de, hl               ;  5  HL: the copy's row 1
        ld de, arows            ; 11  DE: the table
        ld c, 22                ;  8  rows 1 to 22
.row:   ld a, (de)              ;  8  the row's middle name
        inc de                  ;  7
        push af                 ; 12
        ld a, BRICK             ;  8
        ld (hl), a              ;  8
        inc hl                  ;  7
        out (VDP_DATA), a       ; 12  the wall on the left
        pop af                  ; 11
        ld b, 30                ;  8
.mid:   ld (hl), a              ;  8
        inc hl                  ;  7
        out (VDP_DATA), a       ; 12
        djnz .mid               ; 14, or 9: 41 T-states a name
        ld a, BRICK             ;  8
        ld (hl), a              ;  8
        inc hl                  ;  7
        out (VDP_DATA), a       ; 12  and on the right
        dec c                   ;  5
        jr nz, .row             ; 13, or 8
        ex de, hl               ;  5  DE: the copy's row 23
        ld hl, row23            ; 11  the bottom line
; row32: HL = 32 names, DE = where in the copy -> both there and to the VDP.
; Uses A, B, DE, HL
row32:  ld b, 32                ;  8
.name:  ld a, (hl)              ;  8
        ld (de), a              ;  8
        out (VDP_DATA), a       ; 12
        inc hl                  ;  7
        inc de                  ;  7
        djnz .name              ; 14, or 9
        ret                     ; 11

; best: score against hi, the first digits first -> hi is score when score
; is higher. Uses A, BC, DE, HL
best:   ld hl, score            ; 11
        ld de, hi               ; 11
        ld b, 3                 ;  8  three bytes
.byte:  ld a, (de)              ;  8  a byte of hi
        cp (hl)                 ;  8  less the same byte of score
        jr c, .new              ; 13, or 8  score's is higher: a new best
        ret nz                  ; 12, or 6  hi's is higher
        inc l                   ;  5
        inc e                   ;  5  the same: the next byte decides
        djnz .byte              ; 14, or 9
        ret                     ; 11  the same number
.new:   ld c, b                 ;  5  the bytes from here on, this one too;
        ld b, 0                 ;  8  the ones before are the same
        ldir                    ; 23, and 18 the last time
        ret                     ; 11

; addsc: A = points, two BCD digits -> added to score, the carry taken into
; the digits before with ADC and DAA (chapter 9). Uses A, HL
addsc:  ld hl, score + 2        ; 11  the last two digits
        add a, (hl)             ;  8
        daa                     ;  5
        ld (hl), a              ;  8
        dec l                   ;  5  DEC L leaves the carry alone
        ld a, (hl)              ;  8
        adc a, 0                ;  8
        daa                     ;  5
        ld (hl), a              ;  8
        dec l                   ;  5
        ld a, (hl)              ;  8
        adc a, 0                ;  8
        daa                     ;  5
        ld (hl), a              ;  8
        ret                     ; 11

; say: HL = a text ending in a 0 byte, DE = the VRAM address of its first
; character, bit 6 set -> the text sent, HL on its 0. Uses A, HL
say:    ld a, e                 ;  5
        out (VDP_CTRL), a       ; 12
        ld a, d                 ;  5
        out (VDP_CTRL), a       ; 12  the address of the first character
.char:  ld a, (hl)              ;  8  the next character
        or a                    ;  5
        ret z                   ; 12, or 6  the 0: the end
        out (VDP_DATA), a       ; 12
        inc hl                  ;  7
        jr .char                ; 13

; random: the next of the 65,535 states of a 16-bit xorshift, x XOR x << 7,
; XOR x >> 9, XOR x << 8 -> seed, A = its high byte. Uses A, HL
random: ld hl, (seed)           ; 17
        ld a, h                 ;  5
        rra                     ;  5  bit 0 of H into the carry
        ld a, l                 ;  5
        rra                     ;  5  x << 7's high byte: that bit and L >> 1
        xor h                   ;  5
        ld h, a                 ;  5  H XOR it
        ld a, l                 ;  5
        rrca                    ;  5
        and $80                 ;  8  x << 7's low byte: L's bit 0 at bit 7
        xor l                   ;  5
        ld l, a                 ;  5  x XOR x << 7
        ld a, h                 ;  5
        srl a                   ; 10  x >> 9, which is H >> 1
        xor l                   ;  5
        ld l, a                 ;  5  x XOR x >> 9, which changes L alone
        xor h                   ;  5
        ld h, a                 ;  5  x XOR x << 8: H XOR L
        ld (seed), hl           ; 17
        ret                     ; 11

; pace: carry if the player ticks in this frame. Its ticks are 313 lines
; apart, a frame of the 50 Hz machine: each frame adds its own lines to
; owed, and a tick pays 313 of them back. Uses DE, HL
pace:   ld hl, (owed)           ; 17
        ld de, (lines)          ; 22  313 or 262, from INIT
        add hl, de              ; 12
        ld de, -313             ; 11
        add hl, de              ; 12  carry: 313 lines are owed
        jr c, .paid             ; 13, or 8
        sbc hl, de              ; 17  not yet: the 313 given back, no carry
.paid:  ld (owed), hl           ; 17
        ret                     ; 11

; tochip: R0 to R10 from shadow, in order. Uses A, BC, HL
tochip: ld hl, shadow           ; 11
        ld bc, 11 << 8 | PSG_WRITE ; 11  B: the registers; C: the port
        xor a                   ;  5  R0 first
.reg:   out (PSG_ADDR), a       ; 12  the register
        inc a                   ;  5
        outi                    ; 18  its byte; HL on, and B down
        jr nz, .reg             ; 13, or 8
        ret                     ; 11

; play: the next tick into shadow: every SPEED ticks a row of each channel,
; then each channel's level, period and mixer bits, and an effect, if one
; is sounding, over channel C. Uses A, BC, DE, HL, IX
play:   ld hl, (beats)          ; 17  one tick more
        inc hl                  ;  7
        ld (beats), hl          ; 17
        ld hl, tick             ; 11
        dec (hl)                ; 12
        jr nz, .sounds          ; 13, or 8
        ld (hl), SPEED          ; 11  a row
        ld hl, rowno            ; 11
        inc (hl)                ; 12  next sets it to 0 at a new bar
        ld ix, chan_a           ; 16
        call row                ; 18
        ld ix, chan_b           ; 16
        call row                ; 18
        ld ix, chan_c           ; 16
        call row                ; 18
.sounds: ld a, $BF              ;  8  all shut; bit 7 at 1, bit 6 at 0
        ld (shadow + 7), a      ; 14
        ld ix, chan_a           ; 16
        call sound              ; 18
        ld ix, chan_b           ; 16
        call sound              ; 18
        ld ix, chan_c           ; 16
        call sound              ; 18
        ld ix, chan_x           ; 16  an effect?
        ld a, (ix + WAITS)      ; 21  its ticks still to sound
        or a                    ;  5
        ret z                   ; 12, or 6  none: channel C is the music's
        dec (ix + WAITS)        ; 25
        ld a, (shadow + 7)      ; 14  the music's tone and noise on C shut
        or %00100100            ;  8
        ld (shadow + 7), a      ; 14
        jp sound                ; 11  the effect's, whose RET is play's

; row: IX = a channel -> a row: one less to wait, and at none, its pattern's
; next event, and its instrument's tables from their first byte. Uses A,
; BC, DE, HL
row:    dec (ix + WAITS)        ; 25
        ret nz                  ; 12, or 6
        ld l, (ix + PATTERN)    ; 21
        ld h, (ix + PATTERN + 1) ; 21
        ld a, (hl)              ;  8
        inc hl                  ;  7
        cp END                  ;  8  the pattern's end?
        jr nz, .event           ; 13, or 8
        call next               ; 18  the song's next step
        ld a, (hl)              ;  8
        inc hl                  ;  7
.event: bit 7, a                ; 10  an instrument first?
        jr z, .note             ; 13, or 8
        and $7F                 ;  8
        ld (ix + INSTR), a      ; 21
        ld a, (hl)              ;  8
        inc hl                  ;  7
.note:  ld (ix + NOTE), a       ; 21  0 for a rest
        ld a, (hl)              ;  8  the rows it lasts
        inc hl                  ;  7
        ld (ix + WAITS), a      ; 21
        ld (ix + PATTERN), l    ; 21
        ld (ix + PATTERN + 1), h ; 21

; voice: IX = a channel -> its instrument's two tables from their first
; byte, its mixer bits and its noise's period, from instruments, 6 bytes
; each. Leaves the carry clear. Uses A, DE, HL
voice:  ld a, (ix + INSTR)      ; 21
        ld l, a                 ;  5
        add a, a                ;  5
        add a, l                ;  5  three times
        add a, a                ;  5  six times
        ld l, a                 ;  5
        ld h, 0                 ;  8
        ld de, instruments      ; 11
        add hl, de              ; 12  no carry: the table is in the ROM
        ld a, (hl)              ;  8  the volume table
        ld (ix + VOLUME), a     ; 21
        inc hl                  ;  7
        ld a, (hl)              ;  8
        ld (ix + VOLUME + 1), a ; 21
        inc hl                  ;  7
        ld a, (hl)              ;  8  the pitch table
        ld (ix + PITCHES), a    ; 21
        ld (ix + FIRST), a      ; 21
        inc hl                  ;  7
        ld a, (hl)              ;  8
        ld (ix + PITCHES + 1), a ; 21
        ld (ix + FIRST + 1), a  ; 21
        inc hl                  ;  7
        ld a, (hl)              ;  8  the mixer's bits
        ld (ix + MIXER), a      ; 21
        inc hl                  ;  7
        ld a, (hl)              ;  8  the noise's period
        ld (ix + NOISEP), a     ; 21
        ret                     ; 11

; next: the song's next step, or its first after the last: each channel's
; new pattern, and IX's in HL; the bar counted, and its row 0. Uses A, BC,
; DE, HL
next:   ld hl, (songp)          ; 17
        ld de, 6                ; 11
        add hl, de              ; 12
        ld a, (hl)              ;  8
        inc hl                  ;  7
        or (hl)                 ;  8  a word 0: the end
        dec hl                  ;  7
        ld a, (barno)           ; 14
        jr nz, .keep            ; 13, or 8
        ld hl, song             ; 11  the first step again
        xor a                   ;  5
.keep:  inc a                   ;  5
        ld (barno), a           ; 14
        ld (songp), hl          ; 17
        xor a                   ;  5
        ld (rowno), a           ; 14
        ld de, chan_a + PATTERN ; 11
        ldi                     ; 18
        ldi                     ; 18
        ld de, chan_b + PATTERN ; 11
        ldi                     ; 18
        ldi                     ; 18
        ld de, chan_c + PATTERN ; 11
        ldi                     ; 18
        ldi                     ; 18
        ld l, (ix + PATTERN)    ; 21
        ld h, (ix + PATTERN + 1) ; 21
        ret                     ; 11

; sound: IX = a channel -> its level, and for a note its period, in
; shadow, its tables a tick on; its tone and noise opened in R7, and R6
; its noise's period. Uses A, BC, DE, HL
sound:  ld c, 0                 ;  8  a rest's level
        ld a, (ix + NOTE)       ; 21
        or a                    ;  5
        jr z, .level            ; 13, or 8
        ld l, (ix + VOLUME)     ; 21
        ld h, (ix + VOLUME + 1) ; 21
        ld a, (hl)              ;  8  this tick's level
        cp END                  ;  8  the table's end?
        jr nz, .vstep           ; 13, or 8
        dec hl                  ;  7  the last level again
        ld c, (hl)              ;  8
        jr .pitch               ; 13
.vstep: ld c, a                 ;  5
        inc hl                  ;  7
        ld (ix + VOLUME), l     ; 21
        ld (ix + VOLUME + 1), h ; 21
.pitch: ld l, (ix + PITCHES)    ; 21
        ld h, (ix + PITCHES + 1) ; 21
        ld a, (hl)              ;  8  this tick's semitones
        cp LOOP                 ;  8
        jr nz, .hold            ; 13, or 8
        ld l, (ix + FIRST)      ; 21  the first again
        ld h, (ix + FIRST + 1)  ; 21
        ld a, (hl)              ;  8
        jr .pstep               ; 13
.hold:  cp HOLD                 ;  8
        jr nz, .pstep           ; 13, or 8
        dec hl                  ;  7  the last again
        ld a, (hl)              ;  8
        jr .pnote               ; 13
.pstep: inc hl                  ;  7
        ld (ix + PITCHES), l    ; 21
        ld (ix + PITCHES + 1), h ; 21
.pnote: add a, (ix + NOTE)      ; 21  the note they move it to
        add a, a                ;  5
        ld l, a                 ;  5
        ld h, high notes        ;  8  its period, in a page of its own
        ld e, (hl)              ;  8
        inc l                   ;  5
        ld d, (hl)              ;  8
        ld l, (ix + SHPER)      ; 21
        ld h, (ix + SHPER + 1)  ; 21
        ld (hl), e              ;  8
        inc hl                  ;  7
        ld (hl), d              ;  8
.level: ld l, (ix + SHLEV)      ; 21
        ld h, (ix + SHLEV + 1)  ; 21
        ld (hl), c              ;  8
        ld b, (ix + MIXER)      ; 21
        ld a, (shadow + 7)      ; 14
        bit 0, b                ; 10  a tone?
        jr z, .noise            ; 13, or 8
        and (ix + TMASK)        ; 21
.noise: bit 1, b                ; 10  a noise?
        jr z, .mixer            ; 13, or 8
        and (ix + NMASK)        ; 21
        ld (shadow + 7), a      ; 14
        ld a, (ix + NOISEP)     ; 21
        ld (shadow + 6), a      ; 14
        ret                     ; 11
.mixer: ld (shadow + 7), a      ; 14
        ret                     ; 11

; sfx: A = an effect -> it starts on channel C, unless the effect still
; sounding has a higher priority: then carry, and nothing changes. The
; interrupts must be off. Uses A, DE, HL, IX
sfx:    add a, a                ;  5
        add a, a                ;  5  4 bytes an effect
        ld e, a                 ;  5
        ld d, 0                 ;  8
        ld hl, effects          ; 11
        add hl, de              ; 12  its priority, instrument, note, ticks
        ld ix, chan_x           ; 16
        ld a, (ix + WAITS)      ; 21  an effect sounding?
        or a                    ;  5
        ld a, (hl)              ;  8  the new one's priority
        jr z, .take             ; 13, or 8  none
        cp (ix + PRIO)          ; 21
        ret c                   ; 12, or 6  lower: refused
.take:  ld (ix + PRIO), a       ; 21
        inc hl                  ;  7
        ld a, (hl)              ;  8  the instrument, $80 and its number
        and $7F                 ;  8
        ld (ix + INSTR), a      ; 21
        inc hl                  ;  7
        ld a, (hl)              ;  8
        ld (ix + NOTE), a       ; 21
        inc hl                  ;  7
        ld a, (hl)              ;  8
        ld (ix + WAITS), a      ; 21  the ticks it sounds
        jp voice                ; 11  its tables, and no carry
codeend:                        ; the code ends here
